    /**
     * Compatibility context (what 1.8.9 requires) accepts the legacy query. In a core profile it
     * fails, so we fall back to GL30's indexed enumeration.
     */
    private static Set<String> queryExtensions() {
        Set<String> out = new HashSet<>();
        try {
            String all = SteinCoreGl.glGetString(GL11.GL_EXTENSIONS);
            if (all != null && !all.isEmpty()) {
                Collections.addAll(out, all.split(" "));
                return out;
            }
        } catch (Throwable ignored) { // a missing extension query must not stop context creation
            // core profile: GL_EXTENSIONS raises GL_INVALID_ENUM
        }
        try {
            int n = GL11.glGetInteger(GL30.GL_NUM_EXTENSIONS);
            for (int i = 0; i < n; i++) {
                out.add(GL30.glGetStringi(GL11.GL_EXTENSIONS, i));
            }
        } catch (Throwable ignored) { // a missing extension query must not stop context creation
            // no active context: returns an empty set
        }
        return out;
    }
